public void upgrade(Apartment apartment) {
    apartment.squareFootage += 40;

    if (apartment.getClass() != Studio.class)
        apartment.numberOfBedrooms += 1;
}

suggestion_code:
public void upgrade(Apartment apartment) {
    apartment.squareFootage += 40;
    apartment.increaseBedrooms();
}

public abstract class Apartment {
    public int squareFootage;
    public int numberOfBedrooms;

    abstract void setSquareFootage(int sqft);
    public abstract void increaseBedrooms();
}

public class Studio extends Apartment {
    public Studio() {
        this.numberOfBedrooms = 0;
    }

    public void setSquareFootage(int sqft) {
        this.squareFootage = sqft;
    }

    public void increaseBedrooms() {
        // Studios do not have an extra bedroom upon upgrade.
    }
}

public class PenthouseSuite extends Apartment {
    public PenthouseSuite() {
        this.numberOfBedrooms = 4;
    }

    public void setSquareFootage(int sqft) {
        this.squareFootage = sqft;
    }

    public void increaseBedrooms() {
        this.numberOfBedrooms += 1; // Assume every other apartment gains an extra bedroom when upgraded.
    }
}
